<script setup lang="ts">import{Head,Link}from'@inertiajs/vue3';import AdvertiserPortalHeader from '@/components/Advertiser/AdvertiserPortalHeader.vue';defineProps<{advertiser:any;membership:any;invoices:any[]}>();const money=(v:number,c='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency:c}).format((v||0)/100);</script><template><Head title="Advertising Invoices"/><div class="space-y-6 p-6"><AdvertiserPortalHeader title="Invoices" description="Balances, due dates, payments, and refunds." :advertiser="advertiser"/><div class="overflow-hidden rounded-xl border"><table class="w-full text-sm"><thead class="bg-muted/50 text-left"><tr><th class="p-3">Invoice</th><th>Campaign</th><th>Status</th><th>Due</th><th>Total</th><th>Balance</th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id" class="border-t"><td class="p-3"><Link :href="`/advertiser/invoices/${i.id}`" class="font-medium text-primary">{{i.invoice_number}}</Link></td><td>{{i.campaign?.name||'General sponsorship'}}</td><td>{{i.status}}</td><td>{{i.due_at||'—'}}</td><td>{{money(i.total_cents,i.currency)}}</td><td>{{money(i.balance_cents,i.currency)}}</td></tr><tr v-if="!invoices.length"><td colspan="6" class="p-8 text-center text-muted-foreground">No invoices are available.</td></tr></tbody></table></div></div></template>
